import 'package:flutter/material.dart';

class HomeScreen extends StatelessWidget {
  const HomeScreen({super.key});
  @override
  Widget build(BuildContext context) => const Placeholder();
}

class ProductScreen extends StatelessWidget {
  const ProductScreen({super.key, required this.id});
  final int id;
  @override
  Widget build(BuildContext context) => const Placeholder();
}

class NotFoundScreen extends StatelessWidget {
  const NotFoundScreen({super.key});
  @override
  Widget build(BuildContext context) => const Placeholder();
}

Route<dynamic>? onGenerateRoute(RouteSettings settings) {
  Route<dynamic> page(Widget child) =>
      MaterialPageRoute<dynamic>(builder: (_) => child, settings: settings);

  final uri = Uri.parse(settings.name ?? '/');
  final segments = uri.pathSegments;

  if (segments.isEmpty) return page(const HomeScreen());

  if (segments.length == 2 && segments.first == 'product') {
    final id = int.tryParse(segments[1]);
    if (id != null) return page(ProductScreen(id: id));
  }

  return page(const NotFoundScreen());
}
